    def is_tied(row):
        a = np.array(row['option_a_ratings'])
        b = np.array(row['option_b_ratings'])
        return np.sum(a > b) == np.sum(b > a)

    tied_mask = data.apply(is_tied, axis=1)
    tied_data = data[tied_mask]

    if len(tied_data) == 0:
        return 0.5

    return float(tied_data['response'].mean())

